    /// <summary>
    /// Changes the list of pinned stories on a chat page; requires can_edit_stories administrator right in the chat
    /// </summary>
    public Task<TdLib.TdApi.Objects.Ok> SetChatPinnedStoriesAsync(long chatId = default, int[] storyIds = default)
    {

           using var activity =  StartCallActivity("SetChatPinnedStoriesAsync", typeof(SetChatPinnedStories).FullName ?? "SetChatPinnedStoriesAsync");

           try
           {
             return client.SetChatPinnedStoriesAsync(chatId, storyIds);
           }
           catch (Exception ex)
           {
               MarkAsError(activity, ex);
               throw;
           }
    }
